        </Column>
      </Section>
      <Section style={{ padding: [0, 24, 40, 24], gap: 16 }}>
        <Menu
          items={[
            { text: "Docs", href: "https://example.com/docs" },
            { text: "Changelog", href: "https://example.com/changelog" },
            { text: "Support", href: "https://example.com/support" },
