          separator="·"
          style={{ fontSize: 13, color: "#64748b", justifyContent: "center" }}
        />
        <Social
          icons={[
            { name: "X", href: "https://x.com/example" },
            { name: "GitHub", href: "https://github.com/example" },
            { name: "LinkedIn", href: "https://linkedin.com/company/example" },
